.card {
  background: var(--surface);
  border-radius: 16px;
  padding: 2rem;
  box-shadow: var(--shadow);
  border: 1px solid rgba(15, 23, 42, 0.04);
}

.card__header { margin-bottom: 1.75rem; }

h1 {
  margin: 0 0 0.5rem;
  font-size: 1.75rem;
  letter-spacing: -0.01em;
}

.card__lede {
  margin: 0 0 0.75rem;
  color: var(--text-muted);
}

.required-note {
  margin: 0;
  font-size: 0.875rem;
  color: var(--text-muted);
}

.required-marker { color: var(--error); margin-left: 2px; }

.optional-tag {
  font-weight: 400;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.form { display: flex; flex-direction: column; gap: 1.25rem; }

.form-field { display: flex; flex-direction: column; gap: 0.375rem; }

.form-field label {
  font-weight: 600;
  font-size: 0.9375rem;
}

.form-field input {
  font: inherit;
  color: var(--text);
  background: #fff;
  padding: 0.65rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  transition: border-color 0.15s, box-shadow 0.15s;
  width: 100%;
  min-height: 44px;
}

.form-field input:hover { border-color: var(--border-strong); }

.form-field input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-ring);
}

.form-field input[aria-invalid="true"] {
  border-color: var(--error);
  background: var(--error-bg);
}
.form-field input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(185, 28, 28, 0.25);
}

.field-help {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.field-error {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--error);
  font-weight: 500;
}

.form-actions { margin-top: 0.5rem; }

.btn-primary {
  font: inherit;
  font-weight: 600;
  background: var(--accent);
  color: #fff;
  border: 1px solid var(--accent);
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius);
  cursor: pointer;
  min-height: 44px;
  transition: background 0.15s, border-color 0.15s;
}
.btn-primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
.btn-primary:focus-visible {
  outline: 3px solid var(--accent-ring);
  outline-offset: 2px;
}

.form-status {
  margin: 0.5rem 0 0;
  font-size: 0.9375rem;
  color: var(--text);
  min-height: 1.25em;
}
.form-status.is-success { color: #166534; font-weight: 600; }

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

@media (forced-colors: active) {
  .form-field input { border: 1px solid CanvasText; }
  .form-field input:focus { outline: 2px solid Highlight; }
  .btn-primary { border: 1px solid ButtonText; }
}
