  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main" class="page">
    <section class="card" aria-labelledby="form-title">
      <header class="card__header">
        <h1 id="form-title">Contact support</h1>
        <p class="card__lede">
          Tell us how we can help and we'll get back to you within one business day.
        </p>
        <p class="required-note">
          Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
        </p>
      </header>

      <form id="contact-form" class="form" novalidate>
        <div class="form-field">
          <label for="name">
            Full name <span class="required-marker" aria-hidden="true">*</span>
          </label>
          <input
            id="name"
            name="name"
            type="text"
            required
            autocomplete="name"
            aria-describedby="name-error"
          >
          <p id="name-error" class="field-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="email">
            Email address <span class="required-marker" aria-hidden="true">*</span>
          </label>
          <input
            id="email"
            name="email"
            type="email"
            required
            autocomplete="email"
            aria-describedby="email-error"
          >
          <p id="email-error" class="field-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number <span class="optional-tag">(optional)</span></label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-help phone-error"
          >
          <p id="phone-help" class="field-help">
            Include country code, e.g. +1 555 123 4567. Digits, spaces, dashes, parentheses, and a leading + are allowed.
          </p>
          <p id="phone-error" class="field-error" hidden></p>
        </div>

        <div class="form-actions">
          <button type="submit" class="btn-primary">Send message</button>
        </div>

        <p id="form-status" class="form-status" role="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    (function () {
      const form = document.getElementById('contact-form');
      const status = document.getElementById('form-status');

      const fields = {
        name: {
          input: document.getElementById('name'),
          error: document.getElementById('name-error'),
          validate(value) {
            if (!value.trim()) return 'Error: Enter your full name.';
            return '';
          },
        },
        email: {
          input: document.getElementById('email'),
          error: document.getElementById('email-error'),
          validate(value) {
            const v = value.trim();
            if (!v) return 'Error: Enter your email address.';
            const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!re.test(v)) return 'Error: Enter a valid email like name@example.com.';
            return '';
          },
        },
        phone: {
          input: document.getElementById('phone'),
          error: document.getElementById('phone-error'),
          validate(value) {
            const v = value.trim();
            if (!v) return '';
            const re = /^\+?[\d\s\-()]{7,}$/;
            if (!re.test(v)) {
              return 'Error: Enter a valid phone number using digits, spaces, dashes, parentheses, and an optional leading +.';
            }
            return '';
          },
        },
      };

      function showError(field, message) {
        field.error.textContent = message;
        field.error.hidden = false;
        field.input.setAttribute('aria-invalid', 'true');
      }

      function clearError(field) {
        field.error.textContent = '';
        field.error.hidden = true;
        field.input.removeAttribute('aria-invalid');
      }

      function validateField(key) {
        const field = fields[key];
        const message = field.validate(field.input.value);
        if (message) { showError(field, message); return false; }
        clearError(field);
        return true;
      }

      Object.keys(fields).forEach((key) => {
        const field = fields[key];
        field.input.addEventListener('blur', () => validateField(key));
        field.input.addEventListener('input', () => {
          if (field.input.getAttribute('aria-invalid') === 'true') {
            validateField(key);
          }
        });
      });

      form.addEventListener('submit', (event) => {
        event.preventDefault();
        status.textContent = '';
        status.classList.remove('is-success');

        let firstInvalid = null;
        Object.keys(fields).forEach((key) => {
          const ok = validateField(key);
          if (!ok && !firstInvalid) firstInvalid = fields[key].input;
        });

        if (firstInvalid) {
          firstInvalid.focus();
          status.textContent = 'Please fix the highlighted fields and try again.';
          return;
        }

        status.textContent = 'Thanks! Your message has been sent. We\u2019ll get back to you soon.';
        status.classList.add('is-success');
        form.reset();
      });
    })();
  </script>
</body>
